const regionTranslations = {
  en: {
    Norte: "Northern",
    Nordeste: "Northeastern",
    "Centro-Oeste": "Central-West",
    Sudeste: "Southeast",
    Sul: "Southern",
  },
  es: {
    Norte: "Norte",
    Nordeste: "Nordeste",
    "Centro-Oeste": "Centro-Oeste",
    Sudeste: "Sudeste",
    Sul: "Sur",
  },
  fr: {
    Norte: "Nord",
    Nordeste: "Nord-Est",
    "Centro-Oeste": "Centre-Ouest",
    Sudeste: "Sud-Est",
    Sul: "Sud",
  },
};

const normalizeKey = (value) => String(value || "").replace(/\s+/g, " ").trim();

const getSavedLanguage = () => {
  if (typeof window === "undefined") return "pt";
  const savedLanguage = window.localStorage.getItem(LANGUAGE_STORAGE_KEY);
  return SUPPORTED_CODES.has(savedLanguage) ? savedLanguage : "pt";
};

export const getLanguageConfig = (code) =>
  LANGUAGES.find((language) => language.code === code) || LANGUAGES[0];

export const translateString = (value, language) => {
  const source = String(value ?? "");
  if (language === "pt" || !source.trim()) return source;

  const leading = source.match(/^\s*/)?.[0] || "";
  const trailing = source.match(/\s*$/)?.[0] || "";
  const key = normalizeKey(source);
  const dictionary = translations[language] || {};

  if (dictionary[key]) return `${leading}${dictionary[key]}${trailing}`;

  const respondentMapMatch = key.match(/^(.*?) — municípios respondentes$/);
  if (respondentMapMatch) {
    const translatedTitle = translateString(respondentMapMatch[1], language);
    return `${leading}${translatedTitle} — ${dictionary["municípios respondentes"]}${trailing}`;
  }

  if (key.includes("; ")) {
    const translatedItems = key
      .split(";")
      .map((item) => translateString(item.trim(), language))
      .join("; ");
    return `${leading}${translatedItems}${trailing}`;
  }

  if (key.includes(", ")) {
    const items = key.split(",").map((item) => item.trim());
    const translatedItems = items.map((item) => translateString(item, language));
    const hasTranslatedItem = translatedItems.some((item, index) => item !== items[index]);

    if (hasTranslatedItem) {
      return `${leading}${translatedItems.join(", ")}${trailing}`;
    }
  }

  const characterizationMatch = key.match(/^Caracterização (.+)$/);
  if (characterizationMatch) {
    const title = translateString(characterizationMatch[1], language);
    if (language === "en") return `${leading}${title} Characterization${trailing}`;
    if (language === "fr") return `${leading}Caractérisation ${title}${trailing}`;
    return `${leading}Caracterización ${title}${trailing}`;
  }

  const selectedRegionMatch = key.match(/^Região - (.+)$/);
  if (selectedRegionMatch) {
    const translatedRegion =
      regionTranslations[language]?.[selectedRegionMatch[1]] || selectedRegionMatch[1];
    if (language === "en") return `${leading}Region - ${translatedRegion}${trailing}`;
    if (language === "fr") return `${leading}Région - ${translatedRegion}${trailing}`;
    return `${leading}Región - ${translatedRegion}${trailing}`;
  }

  const regionMatch = key.match(/^Região (.+)$/);
  if (regionMatch) {
    const translatedRegion = regionTranslations[language]?.[regionMatch[1]] || regionMatch[1];
    if (language === "en") return `${leading}${translatedRegion} Region${trailing}`;
    if (language === "fr") return `${leading}Région ${translatedRegion}${trailing}`;
    return `${leading}Región ${translatedRegion}${trailing}`;
  }

  const stateMatch = key.match(/^Estado - (.+)$/);
  if (stateMatch) {
    if (language === "en") return `${leading}State - ${stateMatch[1]}${trailing}`;
    if (language === "fr") return `${leading}État - ${stateMatch[1]}${trailing}`;
    return `${leading}Estado - ${stateMatch[1]}${trailing}`;
  }

  const mapInfluenceMatch = key.match(/^Rede de influência - (.+)$/);
  if (mapInfluenceMatch) {
    if (language === "en") {
      return `${leading}Influence network - ${mapInfluenceMatch[1]}${trailing}`;
    }
    if (language === "fr") {
      return `${leading}Réseau d'influence - ${mapInfluenceMatch[1]}${trailing}`;
    }
    return `${leading}Red de influencia - ${mapInfluenceMatch[1]}${trailing}`;
  }

  const levelMatch = key.match(/^Nível ([\dN/D]+)(\/7)?$/);
  if (levelMatch) {
    if (language === "en") {
      return `${leading}Level ${levelMatch[1]}${levelMatch[2] || ""}${trailing}`;
    }
    if (language === "fr") {
      return `${leading}Niveau ${levelMatch[1]}${levelMatch[2] || ""}${trailing}`;
    }
    return `${leading}Nivel ${levelMatch[1]}${levelMatch[2] || ""}${trailing}`;
  }

  const indicatorMatch = key.match(/^Indicador (.+)$/);
  if (indicatorMatch) {
    if (language === "en") return `${leading}Indicator ${indicatorMatch[1]}${trailing}`;
    if (language === "fr") return `${leading}Indicateur ${indicatorMatch[1]}${trailing}`;
    return `${leading}Indicador ${indicatorMatch[1]}${trailing}`;
  }

  const yearMatch = key.match(/^Ano (.+)$/);
  if (yearMatch) {
    if (language === "en") return `${leading}Year ${yearMatch[1]}${trailing}`;
    if (language === "fr") return `${leading}Année ${yearMatch[1]}${trailing}`;
    return `${leading}Año ${yearMatch[1]}${trailing}`;
  }

  const statesCountMatch = key.match(/^(.+) estados$/);
  if (statesCountMatch) {
    if (language === "en") return `${leading}${statesCountMatch[1]} states${trailing}`;
    if (language === "fr") return `${leading}${statesCountMatch[1]} États${trailing}`;
    return `${leading}${statesCountMatch[1]} estados${trailing}`;
  }

  const regionalAverageMatch = key.match(/^Média regional: (.+) · Média nacional: (.+)$/);
  if (regionalAverageMatch) {
    if (language === "en") {
      return `${leading}Regional average: ${regionalAverageMatch[1]} · National average: ${regionalAverageMatch[2]}${trailing}`;
    }
    if (language === "fr") {
      return `${leading}Moyenne régionale : ${regionalAverageMatch[1]} · Moyenne nationale : ${regionalAverageMatch[2]}${trailing}`;
    }
    return `${leading}Promedio regional: ${regionalAverageMatch[1]} · Promedio nacional: ${regionalAverageMatch[2]}${trailing}`;
  }

  const termTranslation = translateIndicatorDescriptionByTerms(key, language);
  if (termTranslation !== key) return `${leading}${termTranslation}${trailing}`;

  return source;
};

const shouldSkipElement = (element) =>
  !element ||
  element.closest(".notranslate") ||
  element.closest("[vw]") ||
  element.closest("[vw-access-button]") ||
  element.closest("[vw-plugin-wrapper]") ||
  element.closest("#language-selector") ||
  element.closest("script") ||
  element.closest("style") ||
  element.closest("svg");

const translateTextNode = (node, language) => {
  const parent = node.parentElement;
  if (shouldSkipElement(parent)) return;

  const cachedText = textSources.get(node);
  const source =
    cachedText && node.nodeValue === cachedText.translated
      ? cachedText.source
      : node.nodeValue;
  const nextValue = translateString(source, language);

  textSources.set(node, {
    source,
    translated: nextValue,
  });

  if (node.nodeValue !== nextValue) {
    node.nodeValue = nextValue;
  }
};

const translateAttributes = (element, language) => {
  if (shouldSkipElement(element)) return;

  ATTRIBUTE_NAMES.forEach((attributeName) => {
    if (!element.hasAttribute(attributeName)) return;

    const sourceAttribute = `data-i18n-source-${attributeName}`;
    const translatedAttribute = `data-i18n-translated-${attributeName}`;
    const currentValue = element.getAttribute(attributeName);
    const cachedSource = element.getAttribute(sourceAttribute);
    const cachedTranslated = element.getAttribute(translatedAttribute);
    const source =
      cachedSource && currentValue === cachedTranslated ? cachedSource : currentValue;
    element.setAttribute(sourceAttribute, source);

    const nextValue = translateString(source, language);
    element.setAttribute(translatedAttribute, nextValue);

    if (element.getAttribute(attributeName) !== nextValue) {
      element.setAttribute(attributeName, nextValue);
    }
  });
};

const applyTranslations = (root, language) => {
  if (!root) return;

  const textWalker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let currentNode = textWalker.nextNode();
  while (currentNode) {
    translateTextNode(currentNode, language);
    currentNode = textWalker.nextNode();
  }

  if (root instanceof Element) {
    translateAttributes(root, language);
  }

  root.querySelectorAll?.("*").forEach((element) => translateAttributes(element, language));
};

const I18nContext = createContext(null);

export const I18nProvider = ({ children }) => {
  const [language, setLanguageState] = useState(getSavedLanguage);

  const setLanguage = useCallback((nextLanguage) => {
    const safeLanguage = SUPPORTED_CODES.has(nextLanguage) ? nextLanguage : "pt";
    setLanguageState(safeLanguage);

    if (typeof window !== "undefined") {
      window.localStorage.setItem(LANGUAGE_STORAGE_KEY, safeLanguage);
      window.dispatchEvent(
        new CustomEvent("inteligente-language-change", {
          detail: { language: safeLanguage },
        })
      );
    }
  }, []);

  useLayoutEffect(() => {
    const root = document.getElementById("root");
    document.documentElement.lang = getLanguageConfig(language).htmlLang;
    const localizedDescription = translateString(DOCUMENT_DESCRIPTION, language);
    document
      .querySelectorAll(
        'meta[name="description"], meta[property="og:description"], meta[name="twitter:description"]',
      )
      .forEach((meta) => meta.setAttribute("content", localizedDescription));
    applyTranslations(root, language);

    const observer = new MutationObserver(() => {
      applyTranslations(root, language);
    });

    if (root) {
      observer.observe(root, {
        childList: true,
        subtree: true,
        characterData: true,
        attributes: true,
        attributeFilter: ATTRIBUTE_NAMES,
      });
    }

    return () => observer.disconnect();
  }, [language]);

  const value = useMemo(
    () => ({
      language,
      setLanguage,
      t: (source) => translateString(source, language),
    }),
    [language, setLanguage]
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
};

export const useI18n = () => {
  const context = useContext(I18nContext);
  if (!context) {
    throw new Error("useI18n must be used inside I18nProvider");
  }
  return context;
};
